INSERT INTO public.questoes (id, material_id, enunciado, referencia, comentario_professor, ordem, publicado) VALUES
('0d65168f-486d-46b3-81e1-2781dd3927be', 'a99a0bc4-f9cc-41ff-887b-861be8696d24', 'São os chefes do Poder Executivo, respectivamente, nas esferas federal, estadual e municipal:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2026 / Prefeitura de Cordilheira Alta Prefeitura - SC / Agente Comunitária de Saúde / Questão: 23', 'O Poder Executivo é exercido, em cada esfera federativa, por um chefe distinto. Na esfera federal, o art. 76 da Constituição Federal estabelece que "o Poder Executivo é exercido pelo Presidente da República, auxiliado pelos Ministros de Estado". Na esfera estadual, o art. 28 da CF trata da eleição do Governador e do Vice-Governador de Estado como chefes do Executivo estadual. Na esfera municipal, o art. 29, caput, da CF refere-se ao "Prefeito e o Vice-Prefeito, eleitos para mandato de quatro anos", que exercem a chefia do Executivo municipal. As demais alternativas erram ao inserir cargos do Poder Legislativo (Senador, Deputado Federal, Deputado Estadual, Vereador) no lugar dos chefes do Executivo correspondentes.', 1, true),
('1bc586ec-b21a-45e8-be03-820e1560d954', 'a99a0bc4-f9cc-41ff-887b-861be8696d24', 'Conforme a Constituição Federal, os rios que sirvam de limites com outros países são bens:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2025 / Prefeitura de Estância Velha - RS / Pintor de Sinalização / Questão: 32', 'A resposta está expressamente prevista no art. 20, III, da Constituição Federal: "são bens da União: (...) III - os lagos, rios e quaisquer correntes de água em terrenos de seu domínio, ou que banhem mais de um Estado, sirvam de limites com outros países, ou se estendam a território estrangeiro ou dele provenham, bem como os terrenos marginais e as praias fluviais." Trata-se de critério de fronteira e de interesse nacional que justifica a titularidade federal sobre tais bens, distinguindo-se dos rios exclusivamente estaduais, tratados no art. 26 da CF.', 2, true),
('3ee66ed3-1891-45f4-af75-95e940798ef5', 'a99a0bc4-f9cc-41ff-887b-861be8696d24', 'Conforme preconiza a Constituição do Estado do Rio Grande do Sul, são bens do Estado: I. Os rios com nascente e foz no território do Estado.II. As áreas, nas ilhas oceânicas e costeiras, que estiverem sob seu domínio, excluídas aquelas sob domínio da União, dos Municípios ou de terceiros.III. Os terrenos marginais dos rios e lagos navegáveis que correm ou ficam situados em seu território, em zonas não alcançadas pela influência das marés. Quais estão corretas?', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2025 / Prefeitura de Aratiba - RS / Inspetor Tributário / Questão: 24', 'As três assertivas reproduzem, respectivamente, os incisos II, V e VI do art. 7º da Constituição do Estado do Rio Grande do Sul, que disciplina os bens estaduais de forma análoga (e mais detalhada) ao art. 26 da CF: "Art. 7º São bens do Estado: (...) II - os rios com nascente e foz no território do Estado; (...) V - as áreas, nas ilhas oceânicas e costeiras, que estiverem sob seu domínio, excluídas aquelas sob domínio da União, dos Municípios ou de terceiros; VI - os terrenos marginais dos rios e lagos navegáveis que correm ou ficam situados em seu território, em zonas não alcançadas pela influência das marés." Como as três assertivas são literais e corretas, o gabarito é a alternativa "E".', 3, true),
('20b71245-a43d-415f-ab54-bc5a8f012f2d', 'a99a0bc4-f9cc-41ff-887b-861be8696d24', 'Conforme a Constituição Federal, a eleição do Governador e do Vice-Governador de Estado, para mandato de quatro anos, será realizada no primeiro domingo de outubro, em primeiro turno, do ano anterior ao do término do mandato do atual Governador, e a posse ocorrerá no dia:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Prefeitura de Cidreira - RS / Guarda Municipal / Questão: 24', 'O art. 28 da Constituição Federal, com a redação dada pela Emenda Constitucional nº 111/2021, dispõe: "A eleição do Governador e do Vice-Governador de Estado, para mandato de quatro anos, realizar-se-á no primeiro domingo de outubro, em primeiro turno, e no último domingo de outubro, em segundo turno, se houver, do ano anterior ao do término do mandato de seus antecessores, e a posse ocorrerá em 6 de janeiro do ano subsequente." Essa alteração, promovida pela EC 111/2021, deslocou a posse de Governadores do dia 1º de janeiro para o dia 6 de janeiro, justamente para não coincidir com a posse do Presidente da República, que passou a ocorrer em 5 de janeiro (art. 82 da CF).', 4, true),
('e9559827-803f-429f-be7a-f77c4ea31774', 'a99a0bc4-f9cc-41ff-887b-861be8696d24', 'Os subsídios do Governador, do Vice-Governador e dos Secretários de Estado serão fixados por:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Assembleia Legislativa do Rio Grande do Sul ALE RS - RS / Técnico Legislativo / Questão: 28', 'O art. 28, parágrafo único, da Constituição Federal estabelece: "Os subsídios do Governador, do Vice-Governador e dos Secretários de Estado serão fixados por lei de iniciativa da Assembleia Legislativa, observado o que dispõem os arts. 37, XI, 39, § 4º, 150, II, 153, III, e 153, § 2º, I." Trata-se de reserva de iniciativa legislativa atribuída ao próprio Poder Legislativo estadual, e não ao Chefe do Executivo, diferentemente do que ocorre em outras matérias remuneratórias sujeitas à iniciativa privativa do Governador.', 5, true),
('9c7445a6-a8bb-4536-998c-9ebbcc484228', 'a99a0bc4-f9cc-41ff-887b-861be8696d24', 'A Constituição Estadual do Rio Grande do Sul define que o Vice-Governador exercerá as funções de Governador nos casos de impedimento deste, bem como as funções que lhe forem conferidas em lei ou delegadas pelo titular, e suceder-lhe-á em caso de vaga. Segundo o disposto no §1º do Art. 80 da referida Constituição, em caso de impedimento simultâneo do Governador e do Vice-Governador, ou de vacância de ambos os cargos, serão sucessivamente chamados a exercer o cargo de Governador o:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Prefeitura de Giruá Prefeitura - RS / Técnico em Contabilidade / Questão: 25', 'A linha sucessória prevista na Constituição do Estado do RS reproduz, por simetria, o modelo federal do art. 80 da Constituição Federal: "Em caso de impedimento do Presidente e do Vice-Presidente, ou vacância dos respectivos cargos, serão sucessivamente chamados ao exercício da Presidência o Presidente da Câmara dos Deputados, o do Senado Federal e o do Supremo Tribunal Federal." Como o Estado não possui Câmara/Senado bicameral nem um tribunal equivalente ao STF, a Constituição Estadual do RS adapta essa ordem sucessória para o Presidente da Assembleia Legislativa e o Presidente do Tribunal de Justiça do Estado, órgãos análogos ao Legislativo e ao Judiciário máximo em nível estadual.', 6, true),
('a7ae1eb3-67ad-4aad-b690-7b3c8efc82ab', 'a99a0bc4-f9cc-41ff-887b-861be8696d24', 'Nos termos da Constituição Federal do Brasil, o Presidente da República e os Governadores dos Estados serão eleitos, juntamente de seus vices, para cumprir mandato de quatro anos, e tomarão posse, respectivamente, nos dias:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2023 / Prefeitura de Faxinal do Soturno Prefeitura - RS / Fiscal Tributário / Questão: 17', 'A Emenda Constitucional nº 111/2021 alterou as datas de posse do Presidente da República e dos Governadores de Estado, que anteriormente coincidiam no dia 1º de janeiro. O art. 82 da CF passou a dispor: "O mandato do Presidente da República é de 4 (quatro) anos e terá início em 5 de janeiro do ano seguinte ao de sua eleição." Já o art. 28 da CF passou a prever que, quanto ao Governador: "a posse ocorrerá em 6 de janeiro do ano subsequente." A mudança teve como objetivo evitar a sobreposição das duas cerimônias e permitir que Governadores possam prestigiar a posse presidencial, além de afastar a posse da data de Ano Novo. A regra de transição (art. 4º da EC 111/2021) determinou que essa nova sistemática só valeria a partir das eleições de 2026, com posse em 2027.', 7, true);
